package dev.dsmp.economy.text;

import dev.dsmp.economy.*;
import com.google.gson.Gson;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;

class TypographyTest {
    private final Gson json=new Gson();
    @Test void oldTextGetsCompatibleDefaultsAndAdvancedCopiesAreIndependent(){var b=json.fromJson("{\"text\":\"Old text\",\"font\":2}",TextBox.class);b.validate();assertFalse(TextTypography.active(b));assertEquals(3,b.lineGap);assertEquals(255,b.textOpacity);var copy=b.copy();copy.bold=true;copy.italic=true;copy.outline=true;copy.letterSpacing=2;copy.lineGap=8;copy.textOpacity=123;copy.shadowColor=0x123456;copy.shadowOffset=3;copy.outlineWidth=1.8f;copy.customBackground=true;copy.backgroundColor=0x223344;copy.validate();b.restore(copy);assertEquals(json.toJson(copy),json.toJson(b));assertNotSame(copy.lineStyles,b.lineStyles);}
    @Test void settingsRoundTripRetainsAllTypography(@TempDir Path dir)throws Exception{var cfg=new TrackerConfig();var b=new TextBox();b.text="Title\nSubtitle";TextTypography.preset(b,0);b.bold=true;b.italic=true;b.letterSpacing=1.5f;b.shadowOffset=2;b.customBackground=true;b.backgroundColor=0x112233;b.textOpacity=190;b.editLine(1).note="Side note";cfg.textBoxes.add(b);var store=new LocalStore(dir);store.saveConfig(cfg);var saved=store.loadConfig().textBoxes.getFirst();assertEquals(json.toJson(b),json.toJson(saved));}
    @Test void everyPresetKeepsWordingPlacementImagesAndNotes(){for(int i=0;i<TextTypography.PRESETS.length;i++){var b=new TextBox();b.text="Hello world\nHave a great day";b.x=.2f;b.y=.7f;b.size=1.5f;var s=b.editLine(1);s.custom=true;s.shape=LineStyle.PILL;s.image="builtin:gem";s.note="Welcome";String id=b.id;TextTypography.preset(b,i);b.validate();assertEquals("Hello world\nHave a great day",b.text);assertEquals(id,b.id);assertEquals(.2f,b.x);assertEquals(.7f,b.y);assertEquals(1.5f,b.size);assertEquals("builtin:gem",b.style(1).image);assertEquals("Welcome",b.style(1).note);assertEquals(LineStyle.PILL,b.style(1).shape);assertEquals(b.startColor,b.style(1).startColor);assertEquals(b.font,b.style(1).font);}}
    @Test void undoRedoCancelAndInvalidEditsPreserveAtomicDrafts(){var b=new TextBox();String original=json.toJson(b);var h=new TextStyleHistory(b);h.edit(v->TextTypography.preset(v,2));String ocean=json.toJson(b);h.edit(v->v.letterSpacing=3);h.undo();assertEquals(ocean,json.toJson(b));h.redo();assertEquals(3,b.letterSpacing);String valid=json.toJson(b);assertThrows(IllegalArgumentException.class,()->h.edit(v->v.letterSpacing=Float.NaN));assertEquals(valid,json.toJson(b));h.undo();h.edit(v->v.italic=true);assertFalse(h.canRedo());h.cancel();assertEquals(original,json.toJson(b));assertFalse(h.canUndo());}
    @Test void historyHasABoundedUndoBudget(){var b=new TextBox();var h=new TextStyleHistory(b);for(int i=0;i<50;i++){int opacity=100+i;h.edit(v->v.textOpacity=opacity);}int count=0;while(h.canUndo()){h.undo();count++;}assertEquals(32,count);}
    @Test void unicodeSpacingCountsCharactersAndEffectsFitMeasuredBounds(){var b=new TextBox();b.text="😀A\nB";b.letterSpacing=3;assertEquals(15,TextTypography.width(b,"😀A",0,(t,f)->t.codePointCount(0,t.length())*6));var normal=StyledTextLayout.measure(b,(t,f)->t.codePointCount(0,t.length())*6);b.outline=true;b.outlineWidth=2;b.shadow=true;b.shadowOffset=4;b.lineGap=12;b.bold=true;var effects=StyledTextLayout.measure(b,(t,f)->t.codePointCount(0,t.length())*6);assertTrue(effects.width()>normal.width());assertTrue(effects.rows().get(1).y()>=effects.rows().getFirst().height()+12);for(int[] size:new int[][]{{320,240},{640,360},{1280,720}}){var bounds=TextLayout.bounds(b,new TextLayout.Measure(java.util.List.of(),effects.width(),effects.height()),size[0],size[1],true);assertTrue(bounds.x()+bounds.width()<=size[0]);assertTrue(bounds.y()+bounds.height()<=size[1]);}}
    @Test void largeIndividualRowsReserveScaledEffectPadding(){var b=new TextBox();b.text="Large row";b.shadow=true;b.shadowOffset=4;b.outline=true;b.outlineWidth=2;b.editLine(0).textSize=2.5f;var row=StyledTextLayout.measure(b,(t,f)->t.length()*6).rows().getFirst();assertTrue(row.height()>=TextLayout.GLYPH_HEIGHT*2.5f+2*4*2.5f);}
    @Test void colorsAndOutlineControlActualLegacyOverrides(){var b=new TextBox();b.text="One\nTwo";var s=b.editLine(1);s.custom=true;s.outline=true;assertTrue(TextTypography.anyOutline(b));TextTypography.outline(b,false);assertFalse(s.outline);assertFalse(TextTypography.anyOutline(b));for(int role=0;role<5;role++){TextTypography.color(b,role,0x123456);assertEquals(0x123456,TextTypography.color(b,role));}assertEquals(0x123456,s.startColor);assertEquals(0x123456,s.endColor);TextTypography.font(b,3);TextTypography.gradient(b,2);assertEquals(3,s.font);assertEquals(2,s.gradient);assertTrue(b.customBackground);}
    @Test void extendedValuesRejectCorruptOrUnboundedStyles(){var b=new TextBox();b.letterSpacing=Float.POSITIVE_INFINITY;assertThrows(IllegalArgumentException.class,b::validate);b.letterSpacing=0;b.outlineWidth=3;assertThrows(IllegalArgumentException.class,b::validate);b.outlineWidth=.6f;b.shadowOffset=-1;assertThrows(IllegalArgumentException.class,b::validate);b.shadowOffset=1;b.textOpacity=256;assertThrows(IllegalArgumentException.class,b::validate);b.textOpacity=255;b.backgroundColor=0xFF112233;assertThrows(IllegalArgumentException.class,b::validate);}
}
